test_suite:
test('starts with empty todos', () => {
  const { result } = renderHook(() => useReducerTodo());
  expect(result.current.todos).toEqual([]);
});

test('add creates item with text and done=false', () => {
  const { result } = renderHook(() => useReducerTodo());
  act(() => result.current.dispatch({ type: 'add', text: 'Buy milk' }));
  expect(result.current.todos).toHaveLength(1);
  expect(result.current.todos[0].text).toBe('Buy milk');
  expect(result.current.todos[0].done).toBe(false);
  expect(result.current.todos[0].id).toBeDefined();
});

test('toggle flips done flag', () => {
  const { result } = renderHook(() => useReducerTodo());
  act(() => result.current.dispatch({ type: 'add', text: 'Task' }));
  const id = result.current.todos[0].id;
  act(() => result.current.dispatch({ type: 'toggle', id }));
  expect(result.current.todos[0].done).toBe(true);
  act(() => result.current.dispatch({ type: 'toggle', id }));
  expect(result.current.todos[0].done).toBe(false);
});

test('delete removes item by id', () => {
  const { result } = renderHook(() => useReducerTodo());
  act(() => result.current.dispatch({ type: 'add', text: 'A' }));
  act(() => result.current.dispatch({ type: 'add', text: 'B' }));
  const id = result.current.todos[0].id;
  act(() => result.current.dispatch({ type: 'delete', id }));
  expect(result.current.todos).toHaveLength(1);
  expect(result.current.todos[0].text).toBe('B');
});

// __hidden__
test('each added item gets a unique id', () => {
  const { result } = renderHook(() => useReducerTodo());
  act(() => result.current.dispatch({ type: 'add', text: 'X' }));
  act(() => result.current.dispatch({ type: 'add', text: 'Y' }));
  const ids = result.current.todos.map((t: any) => t.id);
  expect(new Set(ids).size).toBe(2);
});

solution:
import { useReducer } from 'react';

type Todo = { id: number; text: string; done: boolean };
type State = { todos: Todo[]; nextId: number };
type Action =
  | { type: 'add'; text: string }
  | { type: 'toggle'; id: number }
  | { type: 'delete'; id: number };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case 'add':
      return { todos: [...state.todos, { id: state.nextId, text: action.text, done: false }], nextId: state.nextId + 1 };
    case 'toggle':
      return { ...state, todos: state.todos.map(t => t.id === action.id ? { ...t, done: !t.done } : t) };
    case 'delete':
      return { ...state, todos: state.todos.filter(t => t.id !== action.id) };
    default:
      return state;
  }
}

export function useReducerTodo() {
  const [{ todos }, dispatch] = useReducer(reducer, { todos: [], nextId: 1 });
  return { todos, dispatch };
}
